SELECT role_id, role_name
FROM tbl_dim_role
WHERE role_id = #{roleId}

SELECT EXISTS(
    SELECT 1
    FROM tbl_auth_user_account
    WHERE LOWER(username) = LOWER(#{username})

        AND user_account_id <> #{excludeAccountId}

)

mapper.update:
UPDATE tbl_dim_member_pseudonym
SET role_id = #{roleId},
    team_id = NULL,
    updated_by = #{actor},
    updated_at = #{now}
WHERE member_key = #{memberKey}

UPDATE tbl_auth_user_account
SET is_active = #{active},
    updated_by = #{actor},
    updated_at = #{now}
WHERE user_account_id = #{accountId}

UPDATE tbl_auth_user_account
SET password_hash = #{passwordHash},
    password_algo = #{passwordAlgo},
    updated_by = #{actor},
    updated_at = #{now}
WHERE user_account_id = #{accountId}
